#include <bits/stdc++.h>using namespace std;// easy if and else question// see what word it is and according to that calculate the total by summing the individual sidesint main() {    int t;    cin >> t;    int faces = 0;    while(t-- > 0){        string name;        cin >> name;                if(name == "Tetrahedron")  faces += 4;                if(name == "Cube") faces += 6;            if(name == "Octahedron") faces += 8;                if(name == "Dodecahedron") faces += 12;                if(name == "Icosahedron") faces += 20;            }    cout << faces;}